import { getActiveLanguage } from 'laravel-vue-i18n';

type Catalog = Record<string, string>;

/**
 * Every translation catalog, bundled at build time (no request at runtime).
 * `lang/{locale}.json` holds the app strings; `lang/php_{locale}.json` is
 * generated by the laravel-vue-i18n Vite plugin from Laravel's PHP files
 * (validation, auth, passwords).
 */
const catalogs = import.meta.glob<{ default: Catalog }>(
    '../../../lang/*.json',
    {
        eager: true,
    },
);

export function resolveLanguage(locale: string): Catalog {
    return catalogs[`../../../lang/${locale}.json`]?.default ?? {};
}

/** The active locale as a BCP 47 tag for `Intl` (`fr_BE` → `fr-BE`). */
export function languageTag(): string {
    return getActiveLanguage().replace('_', '-');
}

/** A date and time in the active language, e.g. "30 sept. 2026, 21:14". */
export function formatDateTime(timestamp: string): string {
    return new Intl.DateTimeFormat(languageTag(), {
        dateStyle: 'medium',
        timeStyle: 'short',
    }).format(new Date(timestamp));
}

/**
 * A large number, shortened in the active language, e.g. "171 k" / "171K" /
 * "1,2 M"; `significantDigits` keeps more of it ("43,3 M" instead of "43 M").
 */
export function formatCompactNumber(
    value: number,
    significantDigits?: number,
): string {
    return new Intl.NumberFormat(languageTag(), {
        notation: 'compact',
        maximumSignificantDigits: significantDigits,
    }).format(value);
}

const COMPACT_SUFFIXES: Record<string, number> = {
    '': 1,
    K: 1e3,
    M: 1e6,
    B: 1e9,
};

/**
 * A count as YouTube Music abbreviates it ("43.3M", "2.41K", "1,234"), as a
 * number to format in the active language. Null when it reads otherwise.
 */
export function parseCompactCount(value: string): number | null {
    const match = /^(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)\s*([KMB]?)$/i.exec(
        value.trim(),
    );

    if (!match) {
        return null;
    }

    const amount = Number(match[1].replaceAll(',', ''));
    const factor = COMPACT_SUFFIXES[match[2].toUpperCase()];

    return Math.round(amount * factor);
}

/** A number in the active language, e.g. "1 262" / "1,262". */
export function formatNumber(value: number): string {
    return new Intl.NumberFormat(languageTag()).format(value);
}

/** "il y a 4 minutes" / "4 minutes ago" for a fixed offset in the past. */
export function formatAgo(
    amount: number,
    unit: Intl.RelativeTimeFormatUnit,
): string {
    return new Intl.RelativeTimeFormat(languageTag(), {
        numeric: 'auto',
    }).format(-amount, unit);
}
